// Several photos in a grid: one large and the rest below, with a "+N"
// overlay on the last visible one.
import { graphql, useFragment } from "react-relay";
import * as stylex from "@stylexjs/stylex";
import { albumGridTokens } from "ComponentTokens.stylex";
import UIImage from "UIImage.react";
import UIText from "UIText.react";
import UILink from "UILink.react";

const styles = stylex.create({
  grid: { display: "grid", gap: 2, gridTemplateColumns: "repeat(6, 1fr)" },
  cell: { position: "relative", overflow: "hidden", backgroundColor: albumGridTokens.background },
  first: { gridColumn: "span 6", aspectRatio: "16 / 10" },
  half: { gridColumn: "span 3", aspectRatio: "1" },
  third: { gridColumn: "span 2", aspectRatio: "1" },
  more: { position: "absolute", inset: 0, display: "flex", alignItems: "center", justifyContent: "center", backgroundColor: "rgba(0,0,0,0.45)" },
});

export default function AlbumAttachment({ renderer }) {
  const data = useFragment(
    graphql`
      fragment AlbumAttachment_renderer on AlbumAttachmentStyleRenderer {
        layout_mode
        attachment {
          url
          all_subattachments {
            count
            nodes {
              url
              media {
                id
                accessibility_caption
                image(width: 300) {
                  uri
                  width
                  height
                }
              }
            }
          }
        }
      }
    `,
    renderer,
  );
  const sub = data.attachment?.all_subattachments;
  const nodes = (sub?.nodes ?? []).slice(0, 4);
  const extra = (sub?.count ?? 0) - nodes.length;
  return (
    <div {...stylex.props(styles.grid)}>
      {nodes.map((node, i) => (
        <UILink key={node.media.id} href={node.url} block label={node.media.accessibility_caption} xstyle={[styles.cell, i === 0 ? styles.first : nodes.length === 3 ? styles.half : styles.third]}>
          <UIImage src={node.media.image.uri} fill alt={node.media.accessibility_caption ?? ""} />
          {i === nodes.length - 1 && extra > 0 ? (
            <span {...stylex.props(styles.more)}>
              <UIText type="headline2" color="onAccent">{`+${extra}`}</UIText>
            </span>
          ) : null}
        </UILink>
      ))}
    </div>
  );
}
