import { graphql, useFragment } from "react-relay";
import * as stylex from "@stylexjs/stylex";
import { reelCardTokens } from "ComponentTokens.stylex";
import UIImage from "UIImage.react";
import UIIcon from "UIIcon.react";
import UIText from "UIText.react";
import { UIRow } from "UIStack.react";

const styles = stylex.create({
  frame: { display: "flex", justifyContent: "center", backgroundColor: "#111" },
  reel: { position: "relative", width: 320, aspectRatio: "9 / 16", overflow: "hidden", borderRadius: reelCardTokens.radius },
  footer: { position: "absolute", left: 0, right: 0, bottom: 0, padding: 12, backgroundImage: "linear-gradient(transparent, rgba(0,0,0,0.7))" },
});

export default function ReelAttachment({ renderer }) {
  const data = useFragment(
    graphql`
      fragment ReelAttachment_renderer on ReelAttachmentStyleRenderer {
        overlay_mode
        attachment {
          media {
            __typename
            ... on Video {
              id
              play_count_text
              poster_image {
                uri
              }
            }
          }
        }
      }
    `,
    renderer,
  );
  const video = data.attachment?.media;
  if (!video?.poster_image) {
    return null;
  }
  return (
    <div {...stylex.props(styles.frame)}>
      <div {...stylex.props(styles.reel)}>
        <UIImage src={video.poster_image.uri} fill alt="" />
        <UIRow gap={6} xstyle={styles.footer}>
          <UIIcon name="play" size={14} color="onAccent" filled />
          <UIText type="meta" color="onAccent" weight="semibold">
            {video.play_count_text}
          </UIText>
        </UIRow>
      </div>
    </div>
  );
}
