// A shared post, framed inside the sharing story: the original's header,
// text and attachments, without its feedback.
import { graphql, useFragment } from "react-relay";
import * as stylex from "@stylexjs/stylex";
import { colors, radii } from "BaseTokens.stylex";
import StoryHeader from "StoryHeader.react";
import StoryMessage from "StoryMessage.react";
import SharedStoryInnerAttachments from "SharedStoryInnerAttachments.react";

const styles = stylex.create({
  frame: { marginInline: 16, marginBottom: 12, border: `1px solid ${colors.divider}`, borderRadius: radii.lg, overflow: "hidden" },
});

export default function SharedStoryAttachment({ renderer }) {
  const data = useFragment(
    graphql`
      fragment SharedStoryAttachment_renderer on SharedStoryAttachmentStyleRenderer {
        story {
          id
          comet_sections {
            context_layout {
              ...StoryHeader_contextLayout
            }
            content {
              ...StoryMessage_content
              ...SharedStoryInnerAttachments_content
            }
          }
        }
      }
    `,
    renderer,
  );
  const sections = data.story?.comet_sections;
  if (!sections) {
    return null;
  }
  return (
    <div {...stylex.props(styles.frame)}>
      {sections.context_layout ? <StoryHeader contextLayout={sections.context_layout} /> : null}
      {sections.content ? <StoryMessage content={sections.content} /> : null}
      {sections.content ? <SharedStoryInnerAttachments content={sections.content} /> : null}
    </div>
  );
}
