import { graphql, useFragment } from "react-relay";
import * as stylex from "@stylexjs/stylex";
import { colors } from "BaseTokens.stylex";
import UIImage from "UIImage.react";
import UILink from "UILink.react";

const styles = stylex.create({
  frame: { display: "block", backgroundColor: colors.webWash, borderBlock: `1px solid ${colors.mediaInnerBorder}` },
  ratio: (ratio) => ({ aspectRatio: ratio, width: "100%", maxHeight: 680 }),
});

export default function PhotoAttachment({ renderer }) {
  const data = useFragment(
    graphql`
      fragment PhotoAttachment_renderer on PhotoAttachmentStyleRenderer {
        is_full_width
        attachment {
          url
          media {
            __typename
            ... on Photo {
              id
              accessibility_caption
              image(width: 500) {
                uri
                width
                height
              }
            }
          }
        }
      }
    `,
    renderer,
  );
  const photo = data.attachment?.media;
  const image = photo?.image;
  if (!image) {
    return null;
  }
  return (
    <UILink href={data.attachment.url} block label={photo.accessibility_caption}>
      <span {...stylex.props(styles.frame)}>
        <UIImage src={image.uri} width={image.width} height={image.height} alt={photo.accessibility_caption ?? ""} xstyle={styles.ratio(image.width / image.height)} />
      </span>
    </UILink>
  );
}
