// A video story's player shell: the poster, duration, a play button and
// the controls bar. There's no media element source; playback isn't part of
// the workload. The player's configuration arrives in a deferred payload.
import { useState } from "react";
import { graphql, useFragment } from "react-relay";
import * as stylex from "@stylexjs/stylex";
import { videoPlayerTokens } from "ComponentTokens.stylex";
import UIImage from "UIImage.react";
import UIIcon from "UIIcon.react";
import UIText from "UIText.react";
import UIPressable from "UIPressable.react";
import { UIRow } from "UIStack.react";

const styles = stylex.create({
  player: { position: "relative", backgroundColor: "black", aspectRatio: "16 / 9", overflow: "hidden" },
  play: { position: "absolute", left: "50%", top: "50%", transform: "translate(-50%, -50%)", width: 64, height: 64, borderRadius: "50%", justifyContent: "center", backgroundColor: "rgba(0,0,0,0.55)" },
  controls: { position: "absolute", left: 0, right: 0, bottom: 0, paddingInline: 12, paddingBlock: 8, backgroundImage: "linear-gradient(transparent, rgba(0,0,0,0.6))" },
  duration: { marginInlineStart: "auto" },
  title: { paddingInline: 16, paddingBlock: 8, backgroundColor: videoPlayerTokens.background },
});

function formatDuration(seconds) {
  const m = Math.floor(seconds / 60);
  const s = String(seconds % 60).padStart(2, "0");
  return `${m}:${s}`;
}

export default function VideoAttachment({ renderer }) {
  const data = useFragment(
    graphql`
      fragment VideoAttachment_renderer on VideoAttachmentStyleRenderer {
        autoplay_mode
        attachment {
          media {
            __typename
            ... on Video {
              id
              playable_duration_s
              width
              height
              title {
                text
              }
              poster_image {
                uri
                width
                height
              }
            }
          }
        }
      }
    `,
    renderer,
  );
  const [muted, setMuted] = useState(true);
  const video = data.attachment?.media;
  if (!video?.poster_image) {
    return null;
  }
  return (
    <div>
      <div {...stylex.props(styles.player)} data-video-id={video.id}>
        <UIImage src={video.poster_image.uri} fill alt="" />
        <UIPressable label="Play video" xstyle={styles.play}>
          <UIIcon name="play" size={28} color="onAccent" filled />
        </UIPressable>
        <UIRow gap={12} xstyle={styles.controls}>
          <UIPressable label={muted ? "Unmute" : "Mute"} onPress={() => setMuted((value) => !value)} showOverlay={false}>
            <UIIcon name="mute" size={18} color="onAccent" />
          </UIPressable>
          <UIText type="meta" color="onAccent" xstyle={styles.duration}>
            {formatDuration(video.playable_duration_s ?? 0)}
          </UIText>
          <UIIcon name="expand" size={18} color="onAccent" label="Full screen" />
        </UIRow>
      </div>
      {video.title?.text ? (
        <div {...stylex.props(styles.title)}>
          <UIText weight="semibold" numberOfLines={2}>
            {video.title.text}
          </UIText>
        </div>
      ) : null}
    </div>
  );
}
