// A shared link: the preview image and a card with the domain, title and
// description.
import { graphql, useFragment } from "react-relay";
import * as stylex from "@stylexjs/stylex";
import { colors } from "BaseTokens.stylex";
import { linkCardTokens } from "ComponentTokens.stylex";
import UIImage from "UIImage.react";
import UIText from "UIText.react";
import UILink from "UILink.react";
import { UIColumn } from "UIStack.react";

const styles = stylex.create({
  image: { aspectRatio: "1.91 / 1", width: "100%" },
  card: { paddingBlock: 10, paddingInline: 16, backgroundColor: colors.cardBackgroundFlat, gap: linkCardTokens.gap },
});

export default function ShareAttachment({ renderer }) {
  const data = useFragment(
    graphql`
      fragment ShareAttachment_renderer on ShareAttachmentStyleRenderer {
        card_mode
        attachment {
          url
          title
          description {
            text
          }
          source {
            text
          }
          media {
            __typename
            ... on GenericAttachmentMedia {
              image(width: 500) {
                uri
              }
            }
          }
        }
      }
    `,
    renderer,
  );
  const attachment = data.attachment;
  if (!attachment) {
    return null;
  }
  return (
    <UILink href={attachment.url} block label={attachment.title}>
      {attachment.media?.image ? <UIImage src={attachment.media.image.uri} fill alt="" xstyle={styles.image} /> : null}
      <UIColumn xstyle={styles.card}>
        <UIText type="caption" color="secondary">
          {attachment.source?.text?.toUpperCase()}
        </UIText>
        <UIText weight="semibold" numberOfLines={2}>
          {attachment.title}
        </UIText>
        <UIText type="meta" color="secondary" numberOfLines={1}>
          {attachment.description?.text}
        </UIText>
      </UIColumn>
    </UILink>
  );
}
