// The attachments of a shared post. The same renderers as a story's, except
// that a share can't nest another share.
import { graphql, useFragment } from "react-relay";
import MatchContainer from "react-relay/lib/relay-hooks/MatchContainer";
import loadModuleComponent from "RelayModuleComponent";
import UIErrorBoundary from "UIErrorBoundary.react";

export default function SharedStoryInnerAttachments({ content }) {
  const data = useFragment(
    graphql`
      fragment SharedStoryInnerAttachments_content on StoryContentSection {
        attachment_container {
          story {
            attachments {
              deduplication_key
              styles {
                ...PhotoAttachment_renderer @module(name: "PhotoAttachment.react")
                ...AlbumAttachment_renderer @module(name: "AlbumAttachment.react")
                ...VideoAttachment_renderer @module(name: "VideoAttachment.react")
                ...ReelAttachment_renderer @module(name: "ReelAttachment.react")
                ...ShareAttachment_renderer @module(name: "ShareAttachment.react")
              }
            }
          }
        }
      }
    `,
    content,
  );
  return (data.attachment_container?.story?.attachments ?? []).map((attachment) => (
    <UIErrorBoundary key={attachment.deduplication_key} name="shared_attachment">
      <MatchContainer match={attachment.styles} props={{ mode: "shared" }} loader={loadModuleComponent} />
    </UIErrorBoundary>
  ));
}
